import { useEffect, useRef, useState } from "react";

function App() {
  const [count, setCount] = useState(0);
  const previousCount = useRef(null);

  useEffect(() => {
    previousCount.current = count;
  }, [count]);

  return (
    <>
      <p>Current: {count}</p>
      <p>Previous: {previousCount.current}</p>

      <button onClick={() => setCount(count + 1)}>
        Increase
      </button>
    </>
  );
}

